'use strict';

const appState = { data: null, page: 'for-you', authMode: 'login', quote: null, selectedCardId: null, homeTab: 'finds', busy: false, handoffHandled: false };
const $ = (s) => document.querySelector(s);
const escapeHtml = (value = '') => String(value ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = (cents) => Number.isSafeInteger(cents) ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100) : 'Unknown';
const human = (value = '') => String(value).replace(/[_-]/g, ' ').replace(/^./, (s) => s.toUpperCase());
const shortDate = (value) => value ? new Date(value).toLocaleDateString('en-US', {month:'short',day:'numeric'}) : 'Sample activity';
