  arrow:'M5 12h14M14 7l5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m5 9 7 7 7-7',close:'m6 6 12 12M18 6 6 18',
  sparkle:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3M20 2v4M18 4h4',
  shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3m-4 9 3 3 5-6',
  check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',leaf:'M19 3C7 2 2 9 7 15s15-1 12-12M5 20 16 8',
  target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',
  card:'M3 5h18v14H3V5M3 10h18M6 15h3',logout:'M10 4H4v16h6M9 12h12m-4-4 4 4-4 4',
  info:'M12 11v6M12 7v.1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
