  external:'M14 3h7v7M21 3 11 13M10 4H4v16h16v-6',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',
  gift:'M3 8h18v4H3V8M5 12v9h14v-9M12 8v13M12 8C3 9 5 0 9 3l3 5Zm0 0c9 1 7-8 3-5l-3 5Z',
  food:'M6 3v6M3 3v4a3 3 0 0 0 6 0V3M6 10v11M17 3v18M17 3c-4 4-4 9 0 9',
  plane:'m3 13 7-2 2-8h2l-1 8 7 4v2l-7-2-1 5-2 1-1-7-6 1v-2',
  pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 0 1 14 0ZM15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
